// apkFSWith builds a synthetic web FS carrying the given dist/assets files —
// the injectable-fs seam that lets the /apk tests exercise APK-present,
// -absent and -multiple discovery without rebuilding the embed.
func apkFSWith(names ...string) fstest.MapFS {
	fsys := fstest.MapFS{}
	for _, n := range names {
		fsys["dist/assets/"+n] = &fstest.MapFile{Data: []byte("apk-bytes")}
	}
	return fsys
}

// captureSlog redirects the default slog logger into a buffer (restored on
// cleanup) so tests can assert the WARN lines the /apk surface emits.
func captureSlog(t *testing.T) *bytes.Buffer {
	t.Helper()
	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })
	return &buf
}

// TestApkRedirectPathOnlyLocation pins the D8 redirect contract: an
// APK-bearing build answers GET /apk with 307 and Location EXACTLY the
// path-only asset URL — no scheme, no host — so a reverse-proxy rewrite of
// scheme/host cannot corrupt it; Cache-Control is no-cache (the redirect is
// re-evaluated per probe; the immutable law lives on the target).
func TestApkRedirectPathOnlyLocation(t *testing.T) {
	h := Handler(nil, Options{ApkFS: apkFSWith("mellifera-tv-1.2.3.apk")})
	req := httptest.NewRequest(http.MethodGet, "/apk", nil)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)

	if rec.Code != http.StatusTemporaryRedirect {
		t.Fatalf("GET /apk status = %d, want 307", rec.Code)
	}
	loc := rec.Header().Get("Location")
	want := "/assets/mellifera-tv-1.2.3.apk"
	if loc != want {
		t.Fatalf("Location = %q, want exactly %q (path-only)", loc, want)
	}
	if strings.Contains(loc, "://") || strings.Contains(loc, "//") {
		t.Errorf("Location %q is not path-only", loc)
	}
	if cc := rec.Header().Get("Cache-Control"); cc != "no-cache" {
		t.Errorf("Cache-Control = %q, want no-cache", cc)
	}
}

// TestApkHeadRedirect proves HEAD is mounted explicitly (chi v5.3 does not
// fold HEAD into Get — the SPA probe is a HEAD request): same 307 redirect,
// headers only.
func TestApkHeadRedirect(t *testing.T) {
	h := Handler(nil, Options{ApkFS: apkFSWith("mellifera-tv-1.2.3.apk")})
	req := httptest.NewRequest(http.MethodHead, "/apk", nil)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)

	if rec.Code != http.StatusTemporaryRedirect {
		t.Fatalf("HEAD /apk status = %d, want 307 (HEAD not mounted → chi 405s)", rec.Code)
	}
	if loc := rec.Header().Get("Location"); loc != "/assets/mellifera-tv-1.2.3.apk" {
		t.Errorf("HEAD /apk Location = %q, want /assets/mellifera-tv-1.2.3.apk", loc)
	}
	if rec.Body.Len() != 0 {
		t.Errorf("HEAD /apk body = %d bytes, want none", rec.Body.Len())
	}
}

// TestApkAbsent404NoIndex proves the route is mounted ALWAYS: an APK-less
// build (bare checkout, CI) answers GET /apk with 404 — never the SPA index
// fallback an unregistered route would leak. The FS carries a non-matching
// asset so the assertion binds the name law, not directory emptiness.
func TestApkAbsent404NoIndex(t *testing.T) {
	h := Handler(nil, Options{ApkFS: apkFSWith("mellifera-tv.txt", "other.apk")})
	for _, method := range []string{http.MethodGet, http.MethodHead} {
		req := httptest.NewRequest(method, "/apk", nil)
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, req)

		if rec.Code != http.StatusNotFound {
			t.Fatalf("%s /apk with no packaged APK: status = %d, want 404", method, rec.Code)
		}
		if ct := rec.Header().Get("Content-Type"); strings.HasPrefix(ct, "text/html") {
			t.Errorf("%s /apk Content-Type = %q — leaked the SPA index fallback", method, ct)
		}
		if strings.Contains(rec.Body.String(), "<html") {
			t.Errorf("%s /apk body contains index.html — leaked the SPA fallback", method)
		}
	}
}

// TestApkNoCache pins the no-cache header on the 307 independent of the
// Location contract: the redirect itself must never be cached, or a stale
// redirect would pin an old APK filename after a re-release.
func TestApkNoCache(t *testing.T) {
	h := Handler(nil, Options{ApkFS: apkFSWith("mellifera-tv-9.9.9.apk")})
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/apk", nil))

	if rec.Code != http.StatusTemporaryRedirect {
		t.Fatalf("status = %d, want 307", rec.Code)
	}
	if cc := rec.Header().Get("Cache-Control"); !strings.Contains(cc, "no-cache") {
		t.Errorf("Cache-Control = %q, want no-cache", cc)
	}
}

// TestApkMultipleDeterministicWarns pins the >1-match law: two packaged APKs
// redirect to the lexically-first name — deterministically — and a WARN is
// logged (with the embedded dist this is a boot WARN; the no-clobber release
// contract makes >1 a packaging defect).
func TestApkMultipleDeterministicWarns(t *testing.T) {
	logs := captureSlog(t)
	h := Handler(nil, Options{ApkFS: apkFSWith("mellifera-tv-2.0.0.apk", "mellifera-tv-1.0.0.apk")})
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/apk", nil))

	if rec.Code != http.StatusTemporaryRedirect {
		t.Fatalf("status = %d, want 307", rec.Code)
	}
	if loc := rec.Header().Get("Location"); loc != "/assets/mellifera-tv-1.0.0.apk" {
		t.Fatalf("Location = %q, want the lexically-first /assets/mellifera-tv-1.0.0.apk", loc)
	}
	if !strings.Contains(logs.String(), "multiple packaged TV APKs") {
		t.Errorf("slog output missing the multiple-APK WARN; got %q", logs.String())
	}
}

// TestApkContentTypeRow pins the contentTypeFor row the packaged APK rides on:
// .apk serves as application/vnd.android.package-archive (what a TV download
// manager and browser installers key on), and the octet-stream default is
// unchanged for everything else — only the .apk row was added.
func TestApkContentTypeRow(t *testing.T) {
	if got := contentTypeFor("mellifera-tv-1.2.3.apk"); got != "application/vnd.android.package-archive" {
		t.Errorf("contentTypeFor(.apk) = %q, want application/vnd.android.package-archive", got)
	}
	for _, name := range []string{"unknown.txt", "no-extension", "index.aapk"} {
		if got := contentTypeFor(name); got != "application/octet-stream" {
			t.Errorf("contentTypeFor(%q) = %q, want the unchanged octet-stream default", name, got)
		}
	}
}
